package com.acme.gym.access;

import java.time.LocalDate;

/**
 * Blocks gym entry when the member's membership is not currently valid.
 */
public class MembershipValidityGuard {

    private final MembershipRepository memberships;

    public MembershipValidityGuard(MembershipRepository memberships) {
        this.memberships = memberships;
    }

    public void assertEntryAllowed(String memberId, LocalDate today) {
        Membership m = memberships.requireActive(memberId);
        if (m.getStatus() == MembershipStatus.SUSPENDED) {
            throw new EntryDeniedException(memberId, "membership suspended");
        }
        if (today.isAfter(m.getEndDate())) {
            throw new EntryDeniedException(memberId, "membership expired on " + m.getEndDate());
        }
    }
}

class EntryDeniedException extends RuntimeException {
    public EntryDeniedException(String memberId, String reason) {
        super("Entry denied for " + memberId + ": " + reason);
    }
}

