package com.acme.gym.billing;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * Calculates monthly membership fee from plan rate, discount and tax.
 */
public class MembershipFeeCalculator {

    private final PlanRepository plans;
    private final TaxTable taxes;

    public MembershipFeeCalculator(PlanRepository plans, TaxTable taxes) {
        this.plans = plans;
        this.taxes = taxes;
    }

    public BigDecimal monthlyFee(String memberId, String planCode, String region, BigDecimal discountPct) {
        BigDecimal base = plans.require(planCode).getMonthlyRate();
        BigDecimal discount = base.multiply(discountPct).divide(BigDecimal.valueOf(100), 4, RoundingMode.HALF_UP);
        BigDecimal net = base.subtract(discount);
        BigDecimal tax = taxes.forRegion(region).multiply(net).setScale(4, RoundingMode.HALF_UP);
        return net.add(tax).setScale(2, RoundingMode.HALF_UP);
    }
}

