import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

/**
 * Turnstile entry endpoint: verify, record visit, open turnstile.
 */
@RestController
public class TurnstileEntryController {

    private final MembershipValidityGuard validity;
    private final Turnstile turnstile;
    private final VisitRepository visits;

    public TurnstileEntryController(MembershipValidityGuard validity, Turnstile turnstile, VisitRepository visits) {
        this.validity = validity;
        this.turnstile = turnstile;
        this.visits = visits;
    }

    @PostMapping("/access/entry")
    public VisitView enter(@RequestBody EntryRequest req) {
        validity.assertEntryAllowed(req.getMemberId(), java.time.LocalDate.now());
        turnstile.open(req.getTurnstileId());
        Visit visit = visits.save(new Visit(req.getMemberId(), Instant.now(), req.getTurnstileId()));
        return VisitView.from(visit);
    }
}

