 * Suspends a membership and revokes all currently valid access credentials.
 */
public class MembershipSuspensionService {

    private final MembershipRepository memberships;
    private final AccessCardRepository cards;

    public MembershipSuspensionService(MembershipRepository memberships, AccessCardRepository cards) {
        this.memberships = memberships;
        this.cards = cards;
