        m.setStatus(MembershipStatus.SUSPENDED);
        m.setSuspensionReason(reason);
        m.setSuspendedAt(Instant.now());
        m.setSuspendedBy(actorId);
        memberships.save(m);
        cards.revokeAllForMember(memberId);
    }
}

