package com.acme.gym.rules;

/**
 * Enforces plan inclusion and weekly class booking limit.
 */
public class ClassBookingEligibilityRule {

    private final PlanRepository plans;
    private final ClassBookingRepository bookings;

    public ClassBookingEligibilityRule(PlanRepository plans, ClassBookingRepository bookings) {
        this.plans = plans;
        this.bookings = bookings;
    }

    public void assertEligible(String memberId, String planCode) {
        Plan plan = plans.require(planCode);
        if (!plan.isIncludesGroupClasses()) {
            throw new ClassNotIncludedException(planCode);
        }
        int weekCount = bookings.countInCurrentWeek(memberId);
        if (weekCount >= plan.getWeeklyClassLimit()) {
            throw new ClassLimitReachedException(memberId, weekCount, plan.getWeeklyClassLimit());
        }
    }
}

