package com.acme.gym.audit;

import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Persists an audit row for each membership-affecting event.
 */
public class MembershipEventAuditor {

    private final EntityManager em;

    public MembershipEventAuditor(EntityManager em) {
        this.em = em;
    }

    public void record(String memberId, String eventType, String location, String actorId) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            MembershipAuditEntry e = new MembershipAuditEntry();
            e.setMemberId(memberId);
            e.setEventType(eventType);
            e.setLocation(location);
            e.setActorId(actorId);
            e.setOccurredAt(Instant.now());
            em.persist(e);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

