/* daily_ops_report.c - write daily operations report per facility */
#include <stdio.h>
#include "gym_db.h"

int write_daily_ops(const char *day, const char *path) {
    FILE *out = fopen(path, "w");
    if (!out) return -1;
    fprintf(out, "facility_id,visits,unique_members,classes_held,class_attendance\n");

    db_cursor_t *cur = NULL;
    if (db_open_daily_ops_cursor(&cur, day) != DB_OK) { fclose(out); return -2; }

    int rows = 0;
    ops_row_t row;
    while (db_ops_cursor_next(cur, &row) == DB_OK) {
        fprintf(out, "%s,%d,%d,%d,%d\n",
                row.facility_id, row.visits, row.unique_members,
                row.classes_held, row.class_attendance);
        rows++;
    }
    db_close_cursor(cur);
    fclose(out);
    return rows;
}

